def grid_after(label, text):
    m=re.search(re.escape(label)+r' \((\d+)x(\d+)\):\n((?:[0-9 ]+\n?)+)',text)
    if not m: raise ValueError(label)
    h,w=int(m.group(1)),int(m.group(2)); rows=parse(m.group(3).strip())
    assert len(rows)==h and all(len(r)==w for r in rows),(label,h,w,len(rows),[len(r) for r in rows])
    return rows
